'use strict';
const REPO='Eternal-huang/-',KEY='tju-h2-workflow-v1';
const TASKS={1:[['w1-grid','建立三相配电网基础模型','三相电源 → 线路 → PCC → 三相负荷，保存为 tzm_week1。','模型可运行；记录电源、线路、负荷参数和仿真时长。'],['w1-measure','测量并导出关键量','导出 U_pcc、P_grid、I_abc，确认 AB 线电压 RMS 为一路信号。','U_pcc 为单路有效值，三相电流维度正确，说明功率的符号与单位。'],['w1-plot','绘图并保存数据','绘制电压、功率、三相电流，保存 .mat 数据及绘图脚本。','横轴含时间及单位；图例清楚；脚本可以复现。'],['w1-check','记录结果与问题','解释稳态结果，检查仿真是否覆盖设置的事件。','交付模型、脚本、曲线和简要说明；不要把第一周实测数值当成统一基准。']],2:[['w2-switch','完善第二处负荷投切','在第一周模型中添加第二处三相负荷及投切逻辑，检查投入前后变化。','记录投入时刻；绘制 PCC 电压 RMS、三相电流、有功及无功；无维度报错。'],['w2-battery','建立储能简化功率模型','10 kWh，±20 kW，SOC 初值 0.50，边界 0.20/0.80，时间常数 0.1 s。','正确约定放电为正；SOC 达边界时限制对应方向功率；记录实际输出。'],['w2-electrolyzer','建立电解槽简化功率模型','初始 20 kW，范围 5–30 kW，升降速率各 2 kW/s。','验证功率上下限、爬坡约束；当前模型不等同于完整电解槽物理模型。'],['w2-compare','运行统一扰动并整理交付','仿真 30 s，在 10 s 令负荷 50→60 kW；按统一功率平衡检查结果。','提交 .slx、.m、曲线 / .mat、1 页说明；解释 P_grid、P_el、P_bat、SOC；理想电源不要求频率下降。']]};
let state={member:'',done:{},notes:'',artifact:''};try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved.done==='object'&&saved.done&&!Array.isArray(saved.done))state={...state,...saved};}catch{}
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4500)}
function save(){state.member=$('member').value.trim();state.notes=$('notes').value;state.artifact=$('artifact').value;try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('浏览器无法保存草稿，请导出 JSON 备份。')}}
function render(){const tasks=TASKS[$('week').value],f=$('filter').value;const shown=tasks.filter(t=>f==='all'||(f==='done')===!!state.done[t[0]]);$('taskList').innerHTML=shown.map(t=>`<article class="task"><input type="checkbox" data-task="${t[0]}" aria-label="完成 ${esc(t[1])}" ${state.done[t[0]]?'checked':''}><div><h3>${esc(t[1])}</h3><p>${esc(t[2])}</p><details><summary>查看验收标准</summary><p>${esc(t[3])}</p></details></div></article>`).join('')||'<p>该筛选下暂无任务。</p>';$('draftCount').textContent=`${tasks.filter(t=>state.done[t[0]]).length} / ${tasks.length}`}
$('taskList').addEventListener('change',e=>{const id=e.target.dataset.task;if(id){state.done[id]=e.target.checked;save();render()}});$('week').onchange=render;$('filter').onchange=render;
for(const id of ['member','notes','artifact']){$(id).value=state[id]||'';$(id).addEventListener('input',save)}
$('repoLink').href=`https://github.com/${REPO}`;$('issuesLink').href=`https://github.com/${REPO}/issues`;
$('submitBtn').onclick=()=>{save();if(!state.member){$('member').focus();return toast('先填写成员昵称。')}const week=Number($('week').value),tasks=TASKS[week];const report={schema:'tju-workflow-v1',member:state.member,week,completed:tasks.filter(t=>state.done[t[0]]).map(t=>t[0])};const body=`## 第 ${week} 周进展\n成员：${state.member}\n\n${tasks.map(t=>`- [${state.done[t[0]]?'x':' '}] ${t[1]}`).join('\n')}\n\n### 结果与阻塞\n${state.notes||'请补充结果与需要的帮助。'}\n\n### 成果\n${state.artifact||'请在此拖入文件或粘贴成果链接。'}\n\n<!-- 请保留以下结构化数据，便于自动更新网站进度。 -->\n\n\`\`\`json\n${JSON.stringify(report)}\n\`\`\``;const u=`https://github.com/${REPO}/issues/new?title=${encodeURIComponent(`[周进展] ${state.member} · W${week}`)}&body=${encodeURIComponent(body)}`;window.open(u,'_blank','noopener')};
$('exportBtn').onclick=()=>{save();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='workflow-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('importFile').onchange=async e=>{try{const s=JSON.parse(await e.target.files[0].text());if(typeof s.member!=='string'||typeof s.done!=='object'||!s.done||Array.isArray(s.done))throw Error();state={member:s.member.slice(0,30),done:{},notes:String(s.notes||'').slice(0,2000),artifact:String(s.artifact||'')};Object.values(TASKS).flat().forEach(t=>{state.done[t[0]]=s.done[t[0]]===true});for(const id of ['member','notes','artifact'])$(id).value=state[id];save();render();toast('草稿已导入；团队记录未变更。')}catch{toast('导入失败，请选择有效的草稿 JSON。')}e.target.value=''};
async function team(){try{const r=await fetch('./team-data.json?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();if(!Array.isArray(d.reports))throw Error();$('syncStatus').textContent=d.updatedAt?`快照更新时间：${new Date(d.updatedAt).toLocaleString('zh-CN')} · GitHub 提交后需等待自动部署`:'尚无团队提交快照；提交后由 GitHub 自动更新。';$('teamList').innerHTML=d.reports.length?d.reports.map(x=>`<div class="teamrow"><div><b>${esc(x.member)}</b><br><span>第 ${esc(x.week)} 周 · 自报完成 ${esc(x.completed.length)} / 4</span></div><a href="https://github.com/${REPO}/issues/${Number(x.issue)}" target="_blank" rel="noopener">查看提交 ↗</a></div>`).join(''):'<h3>等待大家的第一次提交</h3><p>团队进度还未填报。完成任意任务后，生成 GitHub 提交即可留下记录。</p>'}catch{$('syncStatus').textContent='暂时无法读取团队快照，请到 GitHub 问题区查看最新提交。';$('teamList').textContent='团队记录加载失败。'}}$('refresh').onclick=team;render();team();
